#include <hwy/highway.h>
#include "stdlib/blas/base/daxpy.h"
#include "stdlib/blas/base/shared.h"

HWY_BEFORE_NAMESPACE();
namespace HWY_NAMESPACE {
	namespace hn = hwy::HWY_NAMESPACE;

	void daxpy_kernel_simd( CBLAS_INT N, double alpha, const double *X, double *Y ) {
		const hn::ScalableTag<double> d;
		const auto alpha_vec = hn::Set( d, alpha );

		// Process in SIMD chunks
		CBLAS_INT i = 0;
		const CBLAS_INT lanes = static_cast<CBLAS_INT>( hn::Lanes( d ) );
		const CBLAS_INT max_i = N - ( N % lanes );

		for ( ; i < max_i; i += lanes ) {
			const auto x = hn::LoadU( d, X + i );
			const auto y = hn::LoadU( d, Y + i );
			const auto result = hn::MulAdd( alpha_vec, x, y );
			hn::StoreU( result, d, Y + i );
		}

		// Scalar tail for remaining elements
		for ( ; i < N; ++i ) {
			Y[i] += alpha * X[i];
		}
	}

	void daxpy_strided_kernel( CBLAS_INT N, double alpha, const double *X, CBLAS_INT strideX, double *Y, CBLAS_INT strideY ) {
		CBLAS_INT ix;
		CBLAS_INT iy;
		CBLAS_INT i;

		if ( alpha == 0.0 ) {
			return;
		}
		ix = 0;
		iy = 0;
		for ( i = 0; i < N; i++ ) {
			Y[ iy ] += alpha * X[ ix ];
			ix += strideX;
			iy += strideY;
		}
	}
} // namespace HWY_NAMESPACE
HWY_AFTER_NAMESPACE();

// Highway-accelerated daxpy. Uses static dispatch to select the SIMD kernel
// compiled for the current target. Declared with C linkage so it can be called
// from both C and C++ translation units.
extern "C" void daxpy_hwy( CBLAS_INT N, double alpha, const double *X, CBLAS_INT strideX, double *Y, CBLAS_INT strideY ) {
	if ( N <= 0 ) {
		return;
	}

	// BLAS convention: for negative strides, adjust pointers so that
	// the first accessed element is at offset zero (stride2offset).
	if ( strideX < 0 ) {
		X += ( 1 - N ) * strideX;
	}
	if ( strideY < 0 ) {
		Y += ( 1 - N ) * strideY;
	}

	if ( strideX == 1 && strideY == 1 ) {
		HWY_STATIC_DISPATCH( daxpy_kernel_simd )( N, alpha, X, Y );
	} else {
		HWY_STATIC_DISPATCH( daxpy_strided_kernel )( N, alpha, X, strideX, Y, strideY );
	}
}
